import signal

import pytest

from twosum import two_sum


class _Timeout(Exception):
    pass


def _with_timeout(fn, seconds):
    def handler(signum, frame):
        raise _Timeout()
    old = signal.signal(signal.SIGALRM, handler)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        return fn()
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, old)


def test_basic():
    assert two_sum([2, 7, 11, 15], 9) == (0, 1)


def test_no_self_pair():
    assert two_sum([3, 3], 6) == (0, 1)


def test_single_no_pair():
    assert two_sum([5], 10) is None


def test_earliest_by_j_then_i():
    # target 10. Pairs: (0,3)=1+9, (1,2)=5+5, (2,4)=5+5... scanning for the
    # smallest completing index j: j=2 (nums[1]+nums[2]=5+5=10) completes before
    # j=3. So the earliest pair is (1, 2), NOT (0, 3).
    nums = [1, 5, 5, 9, 5]
    assert two_sum(nums, 10) == (1, 2)


def test_duplicates_smallest_i_for_that_j():
    # target 8, nums has multiple 4s. Earliest completing j is index 2
    # (nums[0]+nums[2]=4+4). i must be the smallest index that completes it.
    nums = [4, 7, 4, 4]
    assert two_sum(nums, 8) == (0, 2)


def test_no_match():
    assert two_sum([1, 2, 3], 100) is None


def test_performance():
    n = 200_000
    nums = list(range(n))
    target = (n - 1) + (n - 2)
    try:
        result = _with_timeout(lambda: two_sum(nums, target), 3.0)
    except _Timeout:
        pytest.fail("too slow: exceeded 3s (likely O(n^2))")
    assert result == (n - 2, n - 1), f"wrong answer: {result}"

