def two_sum(nums, target):
    """Return the earliest (i, j), i < j, with nums[i] + nums[j] == target.

    Scanning left to right, j is the first index that completes a pair; for
    that j, seen[complement] already holds the smallest earlier index.
    """
    seen = {}
    for j, x in enumerate(nums):
        complement = target - x
        if complement in seen:
            return (seen[complement], j)
        if x not in seen:
            seen[x] = j
    return None
